recipes.code:
{
  "inputs": [
    {
      "id": "sendable-api-key",
      "type": "promptString",
      "description": "Your Sendable API key. Free at https://www.sendable.me/keys",
      "password": true
    }
  ],
  "servers": {
    "sendable": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "sendableme-mcp@1.0.3"
      ],
      "env": {
        "SENDABLE_API_KEY": "${input:sendable-api-key}"
      }
    }
  }
}
